<script>
(()=>{const buttons=[...document.querySelectorAll('[data-step-button]')],panels=[...document.querySelectorAll('[data-step-panel]')];let current=0;
const show=i=>{current=Math.max(0,Math.min(i,buttons.length-1));buttons.forEach((b,n)=>b.className='rounded-xl px-4 py-2.5 text-sm font-bold '+(n===current?'bg-charcoal-900 text-white':'text-neutral-500'));panels.forEach(p=>p.classList.toggle('hidden',p.dataset.stepPanel!==buttons[current].dataset.stepButton));document.getElementById('previousStep')?.classList.toggle('invisible',current===0);document.getElementById('nextStep')?.classList.toggle('hidden',current===buttons.length-1);if(buttons[current].dataset.stepButton==='review')review();window.scrollTo({top:0,behavior:'smooth'})};buttons.forEach((b,i)=>b.onclick=()=>show(i));document.getElementById('previousStep')?.addEventListener('click',()=>show(current-1));document.getElementById('nextStep')?.addEventListener('click',()=>show(current+1));
const conditionals=()=>document.querySelectorAll('[data-show]').forEach(el=>{const [id,wanted]=el.dataset.show.split(':');el.classList.toggle('hidden',document.getElementById(id)?.value!==wanted)});document.querySelectorAll('select').forEach(x=>x.addEventListener('change',conditionals));conditionals();
const review=()=>{const form=document.querySelector('form'),summary=document.getElementById('reviewSummary');if(!summary)return;summary.innerHTML='';[['name','Customer'],['mobile_number','Mobile'],['service_id','Service'],['duty_type_id','Duty Type'],['monthly_salary_budget','Salary Budget'],['monthly_agency_service_charge','Agency Charge'],['house_type','House Type'],['accommodation_provided','Accommodation'],['working_hours_text','Working Hours'],['experience_requirement','Experience']].forEach(([name,label])=>{const el=form.elements[name];let value=el?.value||'Not specified';if(el?.tagName==='SELECT'&&el.selectedIndex>=0)value=el.options[el.selectedIndex].text;summary.insertAdjacentHTML('beforeend',`<div class="rounded-xl bg-neutral-50 p-4"><p class="text-xs font-bold uppercase text-neutral-400">${label}</p><p class="mt-1 font-semibold"></p></div>`);summary.lastElementChild.querySelector('p:last-child').textContent=value})};
document.querySelector('form')?.addEventListener('invalid',e=>{const panel=e.target.closest('[data-step-panel]');const i=buttons.findIndex(b=>b.dataset.stepButton===panel?.dataset.stepPanel);if(i>=0)show(i)},true);show(0)})();
</script>
